CREATE TABLE standing_marks (
      entry TEXT PRIMARY KEY REFERENCES entries (id)
    )

CREATE TRIGGER words_index_entry_removed AFTER DELETE ON entries BEGIN
        DELETE FROM words_index WHERE rowid = OLD.seq * 4 + 0;
      END

CREATE TRIGGER words_index_task_removed AFTER DELETE ON tasks BEGIN
        DELETE FROM words_index WHERE rowid = OLD.seq * 4 + 1;
      END

CREATE TRIGGER words_index_project_removed AFTER DELETE ON projects BEGIN
        DELETE FROM words_index WHERE rowid = OLD.seq * 4 + 2;
      END

CREATE TRIGGER words_index_person_removed AFTER DELETE ON persons BEGIN
        DELETE FROM words_index WHERE rowid = OLD.seq * 4 + 3;
      END

CREATE TRIGGER meaning_entry_made AFTER INSERT ON entries BEGIN

    UPDATE meaning_index SET queued = queued + 1;
    INSERT OR REPLACE INTO meaning_queue (entry, what, queued)
      VALUES (NEW.id, 'embed', (SELECT queued FROM meaning_index));
    END

CREATE TRIGGER meaning_entry_changed AFTER UPDATE OF words ON entries BEGIN

    UPDATE meaning_index SET queued = queued + 1;
    INSERT OR REPLACE INTO meaning_queue (entry, what, queued)
      VALUES (NEW.id, 'embed', (SELECT queued FROM meaning_index));
    END

CREATE TRIGGER meaning_entry_removed AFTER DELETE ON entries BEGIN

    UPDATE meaning_index SET queued = queued + 1;
    INSERT OR REPLACE INTO meaning_queue (entry, what, queued)
      VALUES (OLD.id, 'remove', (SELECT queued FROM meaning_index));
    END
